def find_blocks(grid):
    visited = set()
    blocks = []
    rows, cols = len(grid), len(grid[0])

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and (r,c) not in visited:
                color = grid[r][c]
                block_cells = []
                q = [(r,c)]
                while q:
                    cr, cc = q.pop(0)
                    if cr < 0 or cr >= rows or cc < 0 or cc >= cols or (cr,cc) in visited or grid[cr][cc] != color:
                        continue
                    visited.add((cr,cc))
                    block_cells.append((cr,cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and (nr,nc) not in visited and grid[nr][nc] == color:
                            q.append((nr, nc))
                blocks.append({'color': color, 'cells': block_cells})

    return blocks

